// Formatting helpers for data generated by JavierDB (`python career.py sync`).
// Career facts live in src/data/*.json; components only present them.
import { ui, type Lang } from '../i18n/ui';

export function fmtDate(value?: string | null, lang: Lang = 'en'): string {
  if (!value) return ui[lang].present;
  const [year, month] = value.split('-');
  return month ? `${ui[lang].months[Number(month) - 1]} ${year}` : year;
}

export function fmtRange(start?: string | null, end?: string | null, lang: Lang = 'en'): string {
  return `${fmtDate(start, lang)} – ${fmtDate(end, lang)}`;
}

export function year(value?: string | null): string {
  return value ? value.slice(0, 4) : '';
}

export function firstSentence(text = ''): string {
  const match = text.match(/^.*?[.!?](\s|$)/);
  return (match ? match[0] : text).trim();
}

export function linkUrl(value: string): string {
  return /^https?:\/\//.test(value) ? value : `https://${value}`;
}
